   264→// === Private Functions ===
   265→fun find_available_index(
   266→    pool_reward_manager: &mut PoolRewardManager
   267→): u64{
   268→    let mut i = 0;
   269→    
   270→    while (i < pool_reward_manager.pool_rewards.length()) {
   271→        let optional_pool_reward = pool_reward_manager.pool_rewards.borrow(i);
   272→        if (optional_pool_reward.is_none()) {
   273→            return i
   274→        };
   275→        i = i + 1;
   276→    };
   277→    pool_reward_manager.pool_rewards.push_back(option::none());
   278→    i
   279→}
   280→
   281→fun update_pool_reward_manager(
   282→    pool_reward_manager: &mut PoolRewardManager,
   283→    clock: &Clock
   284→){
   285→    let cur_time_ms = clock.timestamp_ms();
   286→    if(cur_time_ms == pool_reward_manager.last_update_time_ms){
   287→        return 
   288→    };
   289→    
   290→    if (pool_reward_manager.total_shares == 0){
   291→        pool_reward_manager.last_update_time_ms = cur_time_ms;
   292→        return
   293→    };
   294→
   295→    let mut i = 0;
   296→    while (i < pool_reward_manager.pool_rewards.length()){
   297→        let optional_pool_reward = pool_reward_manager.pool_rewards.borrow_mut(i);
   298→        if (optional_pool_reward.is_none()){
   299→            i = i + 1;
   300→            continue
   301→        };
   302→
   303→        let pool_reward = optional_pool_reward.borrow_mut();
   304→        if (
   305→            cur_time_ms <= pool_reward.start_time_ms || 
   306→            pool_reward_manager.last_update_time_ms >= pool_reward.end_time_ms
   307→        ){
   308→            i = i + 1;
   309→            continue
   310→        };
   311→
   312→        let time_passed_ms = 
   313→            cur_time_ms.min(pool_reward.end_time_ms) - 
   314→            pool_reward.start_time_ms.max(pool_reward_manager.last_update_time_ms);
   315→        
   316→        let unlocked_rewards = 
   317→            float::from(pool_reward.total_rewards).mul(
   318→                float::from(time_passed_ms)
   319→            ).div(
   320→            float::from(pool_reward.end_time_ms - pool_reward.start_time_ms)
   321→            );
   322→        
   323→        pool_reward.allocated_rewards = pool_reward.allocated_rewards.add(unlocked_rewards);
   324→        
   325→        pool_reward.cumulative_rewards_per_share = 
   326→            pool_reward.cumulative_rewards_per_share.add(
   327→            unlocked_rewards.div(
   328→                    float::from(pool_reward_manager.total_shares)
   329→                )
   330→            );
   331→        
   332→        i = i + 1;
   333→    };
   334→
   335→    pool_reward_manager.last_update_time_ms = cur_time_ms;
   336→}
   337→
   338→fun update_obligation_reward_manager(
   339→    pool_reward_manager: &mut PoolRewardManager,
   340→    obligation_id: ID,
   341→    clock: &Clock,
   342→    new_obligation_reward_manager: bool,
   343→){
   344→    update_pool_reward_manager(pool_reward_manager, clock);
   345→    
   346→    let obligation_reward_manager = pool_reward_manager.obligation_reward_managers.borrow_mut(obligation_id);
   347→
   348→    let cur_time_ms = clock.timestamp_ms();
   349→    if (!new_obligation_reward_manager && cur_time_ms == obligation_reward_manager.last_update_time_ms){
   350→        return
   351→    };
   352→
   353→    let mut i = 0;
   354→    while(i < pool_reward_manager.pool_rewards.length()){
   355→        let optional_pool_reward = pool_reward_manager.pool_rewards.borrow_mut(i);
   356→        if (optional_pool_reward.is_none()){
   357→            i = i + 1;
   358→            continue
   359→        };
   360→        
   361→        let pool_reward = optional_pool_reward.borrow_mut();
   362→
   363→        while(obligation_reward_manager.rewards.length() <= i){
   364→            obligation_reward_manager.rewards.push_back(option::none());
   365→        };
   366→
   367→        let optional_reward = obligation_reward_manager.rewards.borrow_mut(i);
   368→        if (optional_reward.is_none()){
   369→            if (obligation_reward_manager.last_update_time_ms <= pool_reward.end_time_ms){
   370→                optional_reward.fill(ObligationReward{
   371→                    pool_reward_id: object::id(pool_reward),
   372→                    earned_rewards: {
   373→                        if (obligation_reward_manager.last_update_time_ms <= pool_reward.start_time_ms){
   374→                            pool_reward.cumulative_rewards_per_share.mul(float::from(obligation_reward_manager.share))
   375→                        }else{
   376→                            float::from(0)
   377→                        }
   378→                    },
   379→                    cumulative_rewards_per_share: pool_reward.cumulative_rewards_per_share
   380→                });
   381→                pool_reward.num_obligation_reward_managers = pool_reward.num_obligation_reward_managers + 1;
   382→            };
   383→        }else{
   384→            let reward = optional_reward.borrow_mut();
   385→            let new_rewards = 
   386→                pool_reward.cumulative_rewards_per_share.sub(
   387→                reward.cumulative_rewards_per_share
   388→                ).mul(
   389→                    float::from(obligation_reward_manager.share)
   390→                );
   391→            reward.earned_rewards = reward.earned_rewards.add(new_rewards);
   392→            reward.cumulative_rewards_per_share = pool_reward.cumulative_rewards_per_share;
   393→        };  
   394→
   395→        i = i + 1;
   396→    };
   397→
   398→    obligation_reward_manager.last_update_time_ms = cur_time_ms;
   399→}
