module protocol::liquidity_mining_reward_manager;

// === Imports ===
use std::type_name::{ Self, TypeName };

use sui::balance::Balance;
use sui::clock::Clock;
use sui::bag::{Self, Bag};
use sui::table::{Self, Table};

use math::float::{Self, Decimal};
use protocol::error;

// === Constants ===
const MAX_REWARDS: u64 = 50;
const MIN_REWARD_PERIOD_MS: u64 = 3_600_000;

// === Structs ===
public struct PoolRewardManager has key, store{
    id: UID,
    total_shares: u64,
    pool_rewards: vector<Option<PoolReward>>,
    last_update_time_ms: u64,
    obligation_reward_managers: Table<ID, ObligationRewardManager>
}

public struct PoolReward has key, store {
    id: UID,
    pool_reward_manager_id: ID,
    coin_type: TypeName,
    start_time_ms: u64,
    end_time_ms: u64,
    total_rewards: u64,
    allocated_rewards: Decimal,
    cumulative_rewards_per_share: Decimal,
    num_obligation_reward_managers: u64,
    additional_fields: Bag, 
}

// dynamic field key 
public struct RewardBalance<phantom CoinType> has copy, drop, store {}

public struct ObligationRewardManager has store { 
    share: u64,
    rewards: vector<Option<ObligationReward>>,
    last_update_time_ms: u64,
}

public struct ObligationReward has store {
    pool_reward_id: ID,
    earned_rewards: Decimal,
    cumulative_rewards_per_share: Decimal,
}

// === Public-View Fucntions ===
public fun shares(obligation_reward_manager: &ObligationRewardManager): u64 {
    obligation_reward_manager.share
}

public fun last_update_time_ms(obligation_reward_manager: &ObligationRewardManager): u64 {
    obligation_reward_manager.last_update_time_ms
}

public fun pool_reward_id(pool_reward_manager: &PoolRewardManager, index: u64): ID {
    let optional_pool_reward = pool_reward_manager.pool_rewards.borrow(index);
    let pool_reward = option::borrow(optional_pool_reward);
    object::id(pool_reward)
}

public fun pool_reward(
    pool_reward_manager: &PoolRewardManager,
    index: u64,
): &Option<PoolReward> {
   pool_reward_manager.pool_rewards.borrow( index)
}

public fun total_shares(
    pool_reward_manager: &PoolRewardManager,
): u64{
    pool_reward_manager.total_shares
}

public fun end_time_ms(pool_reward: &PoolReward): u64 {
    pool_reward.end_time_ms
}

// === Public(Package) Functions ===
public(package) fun borrow_obligation_reward_managers(
    pool_reward_manager: &PoolRewardManager,
): &Table<ID, ObligationRewardManager>{
    &pool_reward_manager.obligation_reward_managers
}

public(package) fun new_pool_reward_manager(
    ctx: &mut TxContext,
): PoolRewardManager{
    PoolRewardManager{
        id: object::new(ctx),
        total_shares: 0,
        pool_rewards: vector::empty(),
        last_update_time_ms: 0,
        obligation_reward_managers: table::new<ID, ObligationRewardManager>(ctx),
    }
}

public(package) fun close_pool_reward<CoinType>(
    pool_reward_manager: &mut PoolRewardManager,
    index: u64,
    clock: &Clock
): Balance<CoinType>{
    let optional_pool_reward = pool_reward_manager.pool_rewards.borrow_mut(index);
    let PoolReward{
        id,
        pool_reward_manager_id: _,
        coin_type: _,
        start_time_ms: _,
        end_time_ms,
        total_rewards: _,
        allocated_rewards: _,
        cumulative_rewards_per_share: _,
        num_obligation_reward_managers,
        mut additional_fields,
    } = optional_pool_reward.extract();

    object::delete(id);

    let cur_time_ms = clock.timestamp_ms();

    assert!(cur_time_ms >= end_time_ms, error::liquidity_mining_pool_reward_period_not_over());
    assert!(num_obligation_reward_managers == 0, error::liquidity_mining_not_all_rewards_claimed());

    let reward_balance = additional_fields.remove<RewardBalance<CoinType>, Balance<CoinType>>(RewardBalance<CoinType>{});
    additional_fields.destroy_empty();

    reward_balance
}   

public(package) fun cancel_pool_reward<CoinType>(
    pool_reward_manager: &mut PoolRewardManager,
    index: u64,
    clock: &Clock,
): Balance<CoinType>{
    update_pool_reward_manager(pool_reward_manager, clock);

    let pool_reward = pool_reward_manager.pool_rewards.borrow_mut(index).borrow_mut();
    let cur_time_ms = clock.timestamp_ms();

    let unallocated_rewards = 
        float::from(pool_reward.total_rewards).sub(
        pool_reward.allocated_rewards
        ).floor();

    pool_reward.end_time_ms = cur_time_ms;
    pool_reward.total_rewards = 0;

    let reward_balance = pool_reward.additional_fields.borrow_mut<RewardBalance<CoinType>, Balance<CoinType>>(RewardBalance<CoinType>{});

    reward_balance.split(unallocated_rewards)
}

public(package) fun add_pool_reward<CoinType>(
    pool_reward_manager: &mut PoolRewardManager,
    rewards: Balance<CoinType>,
    start_time_ms: u64,
    end_time_ms: u64,
    clock: &Clock,
    ctx: &mut TxContext
){
    assert!(start_time_ms >= clock.timestamp_ms(), error::liquidity_mining_invalid_start_time());
    assert!(end_time_ms - start_time_ms >= MIN_REWARD_PERIOD_MS, error::liquidity_mining_invalid_time());

    let pool_reward = PoolReward {
        id: object::new(ctx),
        pool_reward_manager_id: object::id(pool_reward_manager),
        coin_type: type_name::with_defining_ids<CoinType>(),
        start_time_ms,
        end_time_ms,
        total_rewards: rewards.value(),
        allocated_rewards: float::from(0),
        cumulative_rewards_per_share: float::from(0),
        num_obligation_reward_managers: 0,
        additional_fields: {
            let mut bag = bag::new(ctx);
            bag.add(RewardBalance<CoinType>{}, rewards);
            bag
        },
    };

    let i = find_available_index(pool_reward_manager);
    assert!(i < MAX_REWARDS, error::liquidity_mining_max_concurrent_pool_rewards_violated());

    let optional_pool_reward = pool_reward_manager.pool_rewards.borrow_mut(i);
    optional_pool_reward.fill(pool_reward);
}

public(package) fun new_obligation_reward_manager(
    pool_reward_manager: &mut PoolRewardManager,
    obligation_id: ID,
    clock: &Clock,
){
    let obligation_reward_manager = ObligationRewardManager{
        share: 0,
        rewards: vector::empty(),
        last_update_time_ms: clock.timestamp_ms(),
    };

    pool_reward_manager.obligation_reward_managers.add(obligation_id, obligation_reward_manager);
    update_obligation_reward_manager(pool_reward_manager, obligation_id, clock, true);
}

public(package) fun change_obligation_reward_manager_share(
    pool_reward_manager: &mut PoolRewardManager,
    obligation_id: ID,
    new_share: u64,
    clock: &Clock,
){
    update_obligation_reward_manager(pool_reward_manager, obligation_id, clock, false);

    let obligation_reward_manager = pool_reward_manager.obligation_reward_managers.borrow_mut(obligation_id);

    pool_reward_manager.total_shares = 
        pool_reward_manager.total_shares - obligation_reward_manager.share + new_share;

    obligation_reward_manager.share = new_share;
}

public(package) fun claim_rewards<CoinType>(
    pool_reward_manager: &mut PoolRewardManager,
    obligation_id: ID,
    clock: &Clock,
    reward_index: u64,
): Balance<CoinType>{
    update_obligation_reward_manager(pool_reward_manager, obligation_id, clock, false);

    let pool_reward = pool_reward_manager.pool_rewards.borrow_mut(reward_index).borrow_mut();

    assert!(pool_reward.coin_type == type_name::with_defining_ids<CoinType>(), error::liquidity_mining_invalid_type());

    let obligation_reward_manager = pool_reward_manager.obligation_reward_managers.borrow_mut(obligation_id);

    let reward_tracker = obligation_reward_manager.rewards.borrow_mut(reward_index);
    assert!(reward_tracker.is_some(), error::liquidity_mining_no_reward_to_claim());

    let reward = reward_tracker.borrow_mut();
    let claimable_rewards = reward.earned_rewards.floor();
    reward.earned_rewards = reward.earned_rewards.sub(float::from(claimable_rewards));

    let reward_balance = pool_reward.additional_fields.borrow_mut<RewardBalance<CoinType>, Balance<CoinType>>(RewardBalance<CoinType>{});

    if (clock.timestamp_ms() >= pool_reward.end_time_ms) {
        // the pool reward has ended, purge the reward at reward_index
        let ObligationReward{
            pool_reward_id: _,
            earned_rewards: _,
            cumulative_rewards_per_share: _,
        } = reward_tracker.extract();

        pool_reward.num_obligation_reward_managers = pool_reward.num_obligation_reward_managers - 1;
    };

    reward_balance.split(claimable_rewards)
}

// === Private Functions ===
fun find_available_index(
    pool_reward_manager: &mut PoolRewardManager
): u64{
    let mut i = 0;

    while (i < pool_reward_manager.pool_rewards.length()) {
        let optional_pool_reward = pool_reward_manager.pool_rewards.borrow(i);
        if (optional_pool_reward.is_none()) {
            return i
        };
        i = i + 1;
    };
    pool_reward_manager.pool_rewards.push_back(option::none());
    i
}

fun update_pool_reward_manager(
    pool_reward_manager: &mut PoolRewardManager,
    clock: &Clock
){
    let cur_time_ms = clock.timestamp_ms();
    if(cur_time_ms == pool_reward_manager.last_update_time_ms){
        return 
    };

    if (pool_reward_manager.total_shares == 0){
        pool_reward_manager.last_update_time_ms = cur_time_ms;
        return
    };

    let mut i = 0;
    while (i < pool_reward_manager.pool_rewards.length()){
        let optional_pool_reward = pool_reward_manager.pool_rewards.borrow_mut(i);
        if (optional_pool_reward.is_none()){
            i = i + 1;
            continue
        };

        let pool_reward = optional_pool_reward.borrow_mut();
        if (
            cur_time_ms <= pool_reward.start_time_ms || 
            pool_reward_manager.last_update_time_ms >= pool_reward.end_time_ms
        ){
            i = i + 1;
            continue
        };

        let time_passed_ms = 
            cur_time_ms.min(pool_reward.end_time_ms) - 
            pool_reward.start_time_ms.max(pool_reward_manager.last_update_time_ms);

        let unlocked_rewards = 
            float::from(pool_reward.total_rewards).mul(
                float::from(time_passed_ms)
            ).div(
            float::from(pool_reward.end_time_ms - pool_reward.start_time_ms)
            );

        pool_reward.allocated_rewards = pool_reward.allocated_rewards.add(unlocked_rewards);

        pool_reward.cumulative_rewards_per_share = 
            pool_reward.cumulative_rewards_per_share.add(
            unlocked_rewards.div(
                    float::from(pool_reward_manager.total_shares)
                )
            );

        i = i + 1;
    };

    pool_reward_manager.last_update_time_ms = cur_time_ms;
}

fun update_obligation_reward_manager(
    pool_reward_manager: &mut PoolRewardManager,
    obligation_id: ID,
    clock: &Clock,
    new_obligation_reward_manager: bool,
){
    update_pool_reward_manager(pool_reward_manager, clock);

    let obligation_reward_manager = pool_reward_manager.obligation_reward_managers.borrow_mut(obligation_id);

    let cur_time_ms = clock.timestamp_ms();
    if (!new_obligation_reward_manager && cur_time_ms == obligation_reward_manager.last_update_time_ms){
        return
    };

    let mut i = 0;
    while(i < pool_reward_manager.pool_rewards.length()){
        let optional_pool_reward = pool_reward_manager.pool_rewards.borrow_mut(i);
        if (optional_pool_reward.is_none()){
            i = i + 1;
            continue
        };

        let pool_reward = optional_pool_reward.borrow_mut();

        while(obligation_reward_manager.rewards.length() <= i){
            obligation_reward_manager.rewards.push_back(option::none());
        };

        let optional_reward = obligation_reward_manager.rewards.borrow_mut(i);
        if (optional_reward.is_none()){
            if (obligation_reward_manager.last_update_time_ms <= pool_reward.end_time_ms){
                optional_reward.fill(ObligationReward{
                    pool_reward_id: object::id(pool_reward),
                    earned_rewards: {
                        if (obligation_reward_manager.last_update_time_ms <= pool_reward.start_time_ms){
                            pool_reward.cumulative_rewards_per_share.mul(float::from(obligation_reward_manager.share))
                        }else{
                            float::from(0)
                        }
                    },
                    cumulative_rewards_per_share: pool_reward.cumulative_rewards_per_share
                });
                pool_reward.num_obligation_reward_managers = pool_reward.num_obligation_reward_managers + 1;
            };
        }else{
            let reward = optional_reward.borrow_mut();
            let new_rewards = 
                pool_reward.cumulative_rewards_per_share.sub(
                reward.cumulative_rewards_per_share
                ).mul(
                    float::from(obligation_reward_manager.share)
                );
            reward.earned_rewards = reward.earned_rewards.add(new_rewards);
            reward.cumulative_rewards_per_share = pool_reward.cumulative_rewards_per_share;
        };  

        i = i + 1;
    };

    obligation_reward_manager.last_update_time_ms = cur_time_ms;
}

